import React, { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { loginToSpotify } from './services/spotifyAuth';
import SpotifyCallback from './components/SpotifyCallback';
import TrackSearch from './components/TrackSearch';

const App = () => {
  const [authValid, setAuthValid] = useState(false);

  // Direct login function to initiate Spotify OAuth
  const handleLogin = () => {
    loginToSpotify();
  };

  return (
    <Router>
      <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
        <h1>Welcome to Track Similarity App</h1>
        <p>
          Use this app to search for tracks based on their rhythm and other parameters. You can
          listen to previews, analyze tracks, and build your perfect DJ set!
        </p>

        {/* If auth is not valid, show login button */}
        {!authValid && (
          <button onClick={handleLogin} style={{ marginBottom: '20px', padding: '10px' }}>
            Login with Spotify
          </button>
        )}

        {/* Route Definitions */}
        <Routes>
          <Route path="/" element={<TrackSearch />} />
          <Route path="/callback" element={<SpotifyCallback />} />
        </Routes>
      </div>
    </Router>
  );
};

export default App;
